"""Regenerate scp03.json using Python cryptography, independently of the Go code.

All keys/challenges below are PUBLIC TEST DATA, never deployment credentials.
Requires `cryptography`; not needed to run the Go tests.
Reference: Yubico/yubihsm-shell lib/yubihsm.c send_authenticated_msg,
send_encrypted_msg, and compute_cryptogram (SCP03), reviewed at revision
6195c1b687aab56308e9598a0d66941813c94ae5.
"""

import argparse
import hashlib
import json
from pathlib import Path

from cryptography.hazmat.primitives import cmac
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes


def mac(key, data):
    c = cmac.CMAC(algorithms.AES(key))
    c.update(data)
    return c.finalize()


def frame(command, data):
    return bytes([command]) + len(data).to_bytes(2, "big") + data


def kdf(key, constant, length):
    data = bytes(11) + bytes([constant, 0]) + (length * 8).to_bytes(2, "big")
    return mac(key, data + b"\x01" + host + card)[:length]


def crypt(key, mode, data):
    ctx = Cipher(algorithms.AES(key), mode).encryptor()
    return ctx.update(data) + ctx.finalize()


def pad(data):
    # SCP03 uses 0x80 followed by zeroes, always at least one byte.
    return data + b"\x80" + bytes(15 - len(data) % 16)


password = b"yubihsm-go public test vector"
key = hashlib.pbkdf2_hmac("sha256", password, b"Yubico", 10000, 32)
host = bytes.fromhex("0001020304050607")
card = bytes.fromhex("08090a0b0c0d0e0f")
sid = b"\x03"
senc = kdf(key[:16], 4, 16)
smac = kdf(key[16:], 6, 16)
srmac = kdf(key[16:], 7, 16)
host_cryptogram = kdf(smac, 1, 8)
card_cryptogram = kdf(smac, 0, 8)
chain = bytes(16)
steps = []


def record(request, response):
    steps.append({"request": request.hex(), "response": response.hex()})


record(frame(3, b"\x00\x01" + host), frame(0x83, sid + card + card_cryptogram))
auth_data = sid + host_cryptogram
auth_frame = bytes([4]) + (len(auth_data) + 8).to_bytes(2, "big") + auth_data
chain = mac(smac, chain + auth_frame)
record(auth_frame + chain[:8], frame(0x84, b""))

for counter, command, payload, response in [
    (1, 1, b"independent transcript", frame(0x81, b"independent transcript")),
    (2, 0x43, b"\xff\xff", frame(0x7f, b"\x0b")),
    (3, 0x40, b"", frame(0xc0, b"")),
]:
    iv = crypt(senc, modes.ECB(), counter.to_bytes(16, "big"))
    ciphertext = crypt(senc, modes.CBC(iv), pad(frame(command, payload)))
    request = bytes([5]) + (1 + len(ciphertext) + 8).to_bytes(2, "big") + sid + ciphertext
    chain = mac(smac, chain + request)
    ciphertext = crypt(senc, modes.CBC(iv), pad(response))
    response = bytes([0x85]) + (1 + len(ciphertext) + 8).to_bytes(2, "big") + sid + ciphertext
    record(request + chain[:8], response + mac(srmac, chain + response)[:8])

expected = json.dumps({
    "description": "Public test transcript, independently generated by Python cryptography (AES-CMAC/AES-CBC).",
    "auth_key": key.hex(),
    "host_challenge": host.hex(),
    "steps": steps,
}, indent=2) + "\n"

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--check", action="store_true", help="verify without overwriting the checked-in oracle")
args = parser.parse_args()
fixture = Path(__file__).with_name("scp03.json")
if args.check:
    if fixture.read_text() != expected:
        raise SystemExit("FAIL: fixed SCP03 transcript differs; review the protocol/oracle before regenerating")
    print("PASS: fixed SCP03 transcript independently reproduced; fixture unchanged.")
else:
    fixture.write_text(expected)
